const transactionResult = await runTransaction<any>(db, async (transaction) => {
  // --- READ PHASE ONLY ---
  if (canReadMissingCheckoutOrder(staffProfile.role)) {
    if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: get order ${newOrderRef.id}`);
    const existingOrderSnap = await transaction.get(newOrderRef);
    if (existingOrderSnap.exists()) {
      const existingOrder = existingOrderSnap.data() as Record<string, unknown>;
      if (
        existingOrder.clientCheckoutIdempotencyKey !== checkoutAttempt.idempotencyKey
        || existingOrder.checkoutPayloadHash !== requestPayloadHash
      ) {
        throw new Error('Checkout retry conflict: an existing order has a different checkout payload.');
      }
      return { existingOrderId: newOrderRef.id };
    }
  }

  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: get counter`);
  const counterDoc = await transaction.get(counterRef);

  let custDoc: any = null;
  if (custRef) {
    if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: get customer doc`);
    custDoc = await transaction.get(custRef);
  }

  let complimentaryAuthorizationData: Record<string, any> | null = null;
  if (complimentaryAuthorizationRef) {
    if (import.meta.env.DEV) console.log('[CHECKOUT] Transaction: get complimentary authorization');
    const authorizationSnapshot = await transaction.get(complimentaryAuthorizationRef);
    if (!authorizationSnapshot.exists()) {
      throw new Error('Complimentary phone verification was not found. Send a new OTP.');
    }
    complimentaryAuthorizationData = authorizationSnapshot.data();
    const expiresAt = complimentaryAuthorizationData.expiresAt;
    const expectedPhoneE164 = `+91${customerPhone.trim()}`;
    if (
      complimentaryAuthorizationData.status !== 'VERIFIED'
      || complimentaryAuthorizationData.used !== false
      || complimentaryAuthorizationData.staffUid !== auth.currentUser!.uid
      || complimentaryAuthorizationData.storeId !== selectedStore.id
      || complimentaryAuthorizationData.customerPhoneE164 !== expectedPhoneE164
      || complimentaryAuthorizationData.provider !== complimentaryVerification!.provider
      || !(expiresAt instanceof Timestamp)
      || expiresAt.toMillis() <= Date.now()
    ) {
      throw new Error('Complimentary phone verification is expired, used, or does not match this sale. Send a new OTP.');
    }
  }

  if (import.meta.env.DEV) console.log('[CHECKOUT] Transaction: get POS add-on authorization');
  const posAddOnAuthorizationSnapshot = await transaction.get(posAddOnAuthorizationRef);
  if (!posAddOnAuthorizationSnapshot.exists()) {
    throw new Error('The POS add-on authorization was not found. Please retry checkout.');
  }
  const posAddOnAuthorizationData = posAddOnAuthorizationSnapshot.data();
  const posAddOnExpiresAt = posAddOnAuthorizationData.expiresAt;
  if (
    posAddOnAuthorizationData.provider !== 'SERVER_CANONICAL_ADD_ONS'
    || posAddOnAuthorizationData.used !== false
    || posAddOnAuthorizationData.staffUid !== auth.currentUser!.uid
    || posAddOnAuthorizationData.storeId !== selectedStore.id
    || posAddOnAuthorizationData.orderId !== newOrderRef.id
    || !(posAddOnExpiresAt instanceof Timestamp)
    || posAddOnExpiresAt.toMillis() <= Date.now()
  ) {
    throw new Error('The POS add-on authorization is expired, used, or does not match this sale.');
  }

  let seq = 1;
  if (counterDoc.exists()) {
    seq = (counterDoc.data()?.lastSequence || 0) + 1;
  }

  const orderNumber = `CB-${selectedStore.code}-${dateKey}-${seq.toString().padStart(4, '0')}`;
  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction validation complete - order number generated: ${orderNumber}`);
  const expandedInventoryLines = expandCompositeInventoryLines(
    validatedCart.map(({ cartItem, liveItem, canonicalAddOns, components }, index) => {
      const liveItemData = liveItem as unknown as Record<string, unknown>;
      return {
        lineKey: orderLineRefs[index].id,
        quantity: cartItem.quantity,
        finishedGood: {
          ...liveItemData,
          code: liveItem.code,
          name: liveItem.name,
          itemType: liveItemData.itemType || cartItem.itemType || 'DIRECT_STOCK',
          bom: Array.isArray(liveItemData.bom)
            ? liveItemData.bom
            : (Array.isArray(cartItem.bom) ? cartItem.bom : []),
          finishedGoodCode: liveItemData.finishedGoodCode || cartItem.finishedGoodCode || liveItem.code,
        } as any,
        addOns: canonicalAddOns,
        components,
      };
    }),
    selectedStore.id,
  );
  const deductionPlan = await planInventoryDeductionForSale({
    transaction,
    store: selectedStore,
    orderId: newOrderRef.id,
    orderNumber,
    orderType,
    businessDate: dateKey,
    source: 'POS',
    staffProfile: {
      uid: auth.currentUser!.uid,
      name: staffProfile.name,
    },
    lines: expandedInventoryLines,
  });

  if (deductionPlan.blockers.length > 0) {
    throw new CheckoutBlockerError(deductionPlan.blockers);
  }

  if (import.meta.env.DEV && deductionPlan.warnings.length > 0) {
    console.warn('[CHECKOUT INVENTORY WARNINGS]', deductionPlan.warnings);
  }

  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction read phase complete`);

  // --- WRITE PHASE ONLY ---
  deductionPlan.stockUpdates.forEach((update) => {
    if (update.existed) {
      traceCheckoutWrite('stock balance update', 'update', update.stockRef.path);
      transaction.update(update.stockRef, {
        currentStock: update.newQty,
        updatedAt: serverTimestamp(),
      });
      return;
    }

    traceCheckoutWrite('sale-created stock row', 'set', update.stockRef.path);
    transaction.set(update.stockRef, {
      ...update.seedData,
      currentStock: update.newQty,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
  });
  deductionPlan.movementPayloads.forEach((movement) => {
    const movementRef = doc(db, 'stockMovements', deterministicStockMovementId(newOrderRef.id, movement));
    traceCheckoutWrite('stock movement create', 'create', movementRef.path);
    transaction.set(movementRef, movement);
  });
  deductionPlan.pendingConsumptionPayloads.forEach((pending) => {
    const pendingRef = doc(db, 'pendingInventoryConsumption', pending.idempotencyKey);
    traceCheckoutWrite('pending BOM create', 'set', pendingRef.path);
    transaction.set(pendingRef, pending, { merge: true });
  });

  if (counterDoc.exists()) {
    if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: updating counter to ${seq}`);
    traceCheckoutWrite('counter update', 'update', counterRef.path);
    transaction.update(counterRef, { lastSequence: seq, updatedAt: serverTimestamp() });
  } else {
    if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: creating counter at ${seq}`);
    traceCheckoutWrite('counter create', 'set', counterRef.path);
    transaction.set(counterRef, { storeCode: selectedStore.code, dateKey, lastSequence: seq, updatedAt: serverTimestamp() });
  }

  // Prepare customer updates
  if (custRef) {
    if (custDoc && custDoc.exists()) {
       if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: update customer`);
      const data = custDoc.data();
      traceCheckoutWrite('customer update', 'update', custRef.path);
      transaction.update(custRef, {
        visitCount: (data.visitCount || 0) + 1,
        totalSpend: (data.totalSpend || 0) + trueGrandTotal,
        lastVisitAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        ...(customerNameFinal && { name: customerNameFinal })
      });
      if (!customerNameFinal && data.name) customerNameFinal = data.name;
    } else {
      if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: create customer`);
      traceCheckoutWrite('customer create', 'set', custRef.path);
      transaction.set(custRef, {
        name: customerNameFinal || 'Unknown',
        phone: phoneToSearch,
        visitCount: 1,
        totalSpend: trueGrandTotal,
        lastVisitAt: serverTimestamp(),
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      });
    }
    customerId = custRef.id;
  }

  const paymentStatus: Order['paymentStatus'] = isComplimentaryCheckout
    ? 'NOT_REQUIRED'
    : isSplitPayment
    ? splitPaymentStatus(paymentRows, trueGrandTotal)
    : (selectedPaymentMethod === 'CREDIT' && trueGrandTotal > 0) ? 'UNPAID' : 'PAID';

  const orderData: Order & Record<string, unknown> = {
    orderNumber,
    storeId: selectedStore.id,
    storeCode: selectedStore.code,
    storeName: selectedStore.name,
    customerId,
    customerName: customerNameFinal,
    customerPhone: phoneToSearch || null,
    createdByUserId: auth.currentUser!.uid,
    createdByName: staffProfile.name,
    orderType,
    status: 'COMPLETED',
    paymentStatus,
    commercialStatus: isComplimentaryCheckout ? 'COMPLIMENTARY' : 'SALE',
    isSetupTest: isSetupTestSale,
    setupTestMode: isSetupTestSale,
    setupTestLabel: isSetupTestSale ? 'SETUP TEST' : null,
    setupTestStoreStatus: isSetupTestSale ? String(selectedStore.status || 'DRAFT') : null,
    addOnAuthorizationId: posAddOnAuthorization.authorizationId,
    addOnTotal: posAddOnAuthorization.canonicalAddOnTotal,
    ...(isComplimentaryCheckout && {
      menuValue: trueSubtotal,
      complimentaryDiscount: trueSubtotal,
      complimentaryReason: complimentaryReason.trim(),
      complimentaryAuthorizationId: complimentaryVerification!.authorizationId,
      complimentaryOtpVerified: true,
      complimentaryVerifiedPhone: complimentaryVerification!.verifiedPhone,
      complimentaryOtpProvider: complimentaryVerification!.provider,
      complimentaryAuthorisedByUid: auth.currentUser!.uid,
      complimentaryAuthorisedByName: staffProfile.name,
      complimentaryAuthorisedAt: serverTimestamp(),
    }),
    tableNumber: tableNumber.trim() || null,
    subtotal: trueSubtotal,
    taxTotal: trueTaxTotal,
    gstTotal: trueTaxTotal,
    taxableAmount: trueTaxableAmount,
    discountPercent: trueDiscountPercent,
    discountAmount: trueDiscount,
    discountTotal: trueDiscount,
    discount: trueDiscount,
    grandTotal: trueGrandTotal,
    cogsTotal: deductionPlan.totalCogs,
    inventoryWarningCount: deductionPlan.warnings.length,
    inventoryWarnings: deductionPlan.warnings.map((warning) => warning.message),
    inventoryConsumptionStatus: deductionPlan.pendingConsumptionPayloads.length > 0 ? 'PENDING_BOM' : 'APPLIED',
    stockMovementCount: deductionPlan.movementPayloads.length,
    clientCheckoutIdempotencyKey: checkoutAttempt.idempotencyKey,
    checkoutPayloadHash: requestPayloadHash,
    checkoutIdempotencyVersion: 1,
    paymentMethod: (paymentRows[0]?.method || selectedPaymentMethod) as PaymentMethod,
    receiptLegalDetails: receiptLegalDetailsFromStore(selectedStore),
    ...(isSplitPayment && {
      isSplitPayment: true,
      paymentMethodLabel: buildPaymentLabel(paymentRows),
      paymentBreakdown: paymentRows,
    }),
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp()
  };

  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: saving order data...`);
  traceCheckoutWrite('order save', 'create', newOrderRef.path);
  transaction.set(newOrderRef, orderData);
  traceCheckoutWrite('POS add-on authorization consume', 'update', posAddOnAuthorizationRef.path);
  transaction.update(posAddOnAuthorizationRef, {
    used: true,
    usedAt: serverTimestamp(),
    orderNumber,
  });
  if (complimentaryAuthorizationRef) {
    traceCheckoutWrite('complimentary authorization consume', 'update', complimentaryAuthorizationRef.path);
    transaction.update(complimentaryAuthorizationRef, {
      used: true,
      usedAt: serverTimestamp(),
      usedByOrderId: newOrderRef.id,
      usedByOrderNumber: orderNumber,
    });
  }

  // Prep line items
  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: saving line items...`);
  const newItems: OrderItem[] = [];
  validatedCart.forEach(({ cartItem: item, liveItem, canonicalAddOns, components }, index) => {
    const lineRef = orderLineRefs[index];
    const lineAddOnTotal = addOnTotal(canonicalAddOns);
    const lineUnitPrice = liveItem.price + lineAddOnTotal;
    const lineSub = lineUnitPrice * item.quantity;
    const lineDiscount = isComplimentaryCheckout ? lineSub : lineSub * trueDiscountRatio;
    const lineTaxable = Math.max(0, lineSub - lineDiscount);
    const appliedTaxRate = getItemTaxRate(liveItem, selectedStoreTaxConfig.rate);
    const baseTaxable = Math.max(0, liveItem.price * item.quantity * (1 - trueDiscountRatio));
    const lineTax = isComplimentaryCheckout
      ? 0
      : baseTaxable * (appliedTaxRate / 100) + addOnTaxForLine(canonicalAddOns, item.quantity, trueDiscountRatio);
    const linePrepStation = normalizePrepStation(liveItem.prepStation);
    const parentInventory = summarizeParentInventory({
      parentLineKey: lineRef.id,
      expandedLines: expandedInventoryLines,
      perLineCogs: deductionPlan.perLineCogs,
      perLineConsumptionStatus: deductionPlan.perLineConsumptionStatus,
    });

    const itemData: OrderItem = {
      menuItemId: liveItem.id,
      itemName: liveItem.name,
      itemCode: liveItem.code,
      categoryId: liveItem.categoryId,
      categoryName: liveItem.categoryName,
      quantity: item.quantity,
      unitPrice: liveItem.price,
      baseUnitPrice: liveItem.price,
      addOns: canonicalAddOns,
      addOnAuthorizationId: posAddOnAuthorization.authorizationId,
      addOnTotal: lineAddOnTotal,
      unitPriceWithAddOns: lineUnitPrice,
      taxRate: appliedTaxRate,
      lineSubtotal: lineSub,
      lineDiscount,
      lineTaxable,
      lineTax: lineTax,
      lineTotal: lineTaxable + lineTax,
      cogsAmount: parentInventory.cogsAmount,
      inventoryConsumptionStatus: parentInventory.inventoryConsumptionStatus,
      prepStation: linePrepStation,
      status: 'PENDING',
      createdAt: serverTimestamp(),
      sourceSystem: 'FINISHED_GOODS',
      itemType: item.itemType,
      finishedGoodCode: item.finishedGoodCode,
      ...(components.length > 0 ? { components } : {}),
    };

    if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: set lineItem ${lineRef.id}`);
    traceCheckoutWrite('order-line save', 'create', lineRef.path);
    transaction.set(lineRef, itemData);
    newItems.push({ id: lineRef.id, ...itemData });

    // Create KOT items
    const createKotItem = (task: CompositeKotTask) => {
      const kotRef = doc(db, 'kotItems', deterministicKotId(newOrderRef.id, lineRef.id, task.taskKey));
      if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: set kotItem ${kotRef.id} for station: ${task.station}`);
      traceCheckoutWrite(`KOT save ${task.station}`, 'create', kotRef.path);
      transaction.set(kotRef, {
        orderId: newOrderRef.id,
        orderNumber,
        orderItemId: lineRef.id,
        storeId: selectedStore.id,
        storeCode: selectedStore.code,
        storeName: selectedStore.name,
        station: task.station,
        itemName: task.itemName,
        itemCode: task.itemCode,
        quantity: task.quantity,
        addOns: canonicalAddOns,
        ...(task.component ? { component: task.component } : {}),
        orderType,
        tableNumber: orderType === 'DINE_IN' ? tableNumber.trim() : null,
        customerName: customerNameFinal,
        status: "PENDING",
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        createdByUserId: auth.currentUser!.uid,
        createdByName: staffProfile.name
      });
    };

    buildKotTasks({
      quantity: item.quantity,
      finishedGood: {
        code: liveItem.code,
        name: liveItem.name,
        displayName: liveItem.name,
        prepStation: linePrepStation,
      },
      components,
    }).forEach(createKotItem);
  });

  // Prep payment
  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction: saving payment data...`);
  const paymentsToWrite: ReceiptPaymentSnapshot[] = isComplimentaryCheckout
    ? []
    : isSplitPayment
    ? paymentRows
    : [{
      method: selectedPaymentMethod as PaymentMethod,
      amount: paymentStatus === 'PAID' ? trueGrandTotal : 0,
    }];
  const newPayments: OrderPayment[] = [];
  paymentsToWrite.forEach((payment, index) => {
    const paymentRef = doc(collection(newOrderRef, 'payments'), deterministicPaymentId(newOrderRef.id, payment, index));
    const paymentData: OrderPayment = {
      method: payment.method,
      amount: payment.amount,
      reference: null,
      paymentIndex: index,
      createdAt: serverTimestamp()
    };
    traceCheckoutWrite('payment save', 'create', paymentRef.path);
    transaction.set(paymentRef, paymentData);
    newPayments.push({ id: paymentRef.id, ...paymentData });
  });

  if (import.meta.env.DEV) console.log(`[CHECKOUT] Transaction write phase complete`);

  return { savedOrder: { id: newOrderRef.id, ...orderData }, savedItems: newItems, savedPayments: newPayments };
});

